steps.solution:
import csv
present, aside = {}, 0
with open("register.csv") as f:
    for row in csv.DictReader(f):
        s = row["status"].strip().upper()
        if s not in ("P", "A"):
            aside += 1
        elif s == "P":
            present[row["class"]] = present.get(row["class"], 0) + 1
for c in sorted(present):
    print(c, present[c])
print("aside", aside)

