steps.solution:
import csv
SUBJECTS = ["maths", "science"]
def problems(row):
    out = []
    if row["subject"] not in SUBJECTS:
        out.append("unknown subject")
    if not row["mark"].isdigit():
        out.append("mark not a number")
    elif int(row["mark"]) > 20:
        out.append("mark out of range")
    return out
with open("marks.csv") as f:
    for n, row in enumerate(csv.DictReader(f), 2):
        for p in problems(row):
            print("line", n, p)

