readings = [1.2, 1.3, 2.6, 1.3, 1.4, 1.6, 1.9, 2.1, 2.3, 2.4, 2.6]
def first_alert(readings, k):
    for i in range(k - 1, len(readings)):
        window = readings[i - k + 1:i + 1]
        if sum(window) / k > 2.0:
            return i
    return None
